-- Hand-edited: an emptied original stays emptied (#184: deleted for good, never restored) whoever
-- writes — purged_at, once set, never changes, and the CHECKs keep the content empty while it is
-- set. The other columns stay as the API keeps them (an operator may still hide a deleted post).
-- TRUNCATE fires no row trigger.
CREATE FUNCTION keep_purged() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.purged_at IS NOT NULL AND NEW.purged_at IS DISTINCT FROM OLD.purged_at THEN
    RAISE EXCEPTION '% % was emptied at % after its retention period and stays so', TG_TABLE_NAME,
      OLD.id, OLD.purged_at
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER posts_keep_purged
  BEFORE UPDATE ON "posts"
  FOR EACH ROW EXECUTE FUNCTION keep_purged();--> statement-breakpoint
CREATE TRIGGER post_comments_keep_purged
  BEFORE UPDATE ON "post_comments"
  FOR EACH ROW EXECUTE FUNCTION keep_purged();--> statement-breakpoint
-- Hand-edited: the purge records are operational records, kept with no period (#57-18) and never
-- rewritten. buddha_app keeps SELECT/INSERT of the default privileges in
-- docker/postgres/init/01-roles.sql and loses UPDATE and DELETE.
REVOKE UPDATE, DELETE ON TABLE "retention_purges" FROM buddha_app;--> statement-breakpoint
-- Hand-edited: buddha_app cannot DELETE an approval request (migration 0021: the table is the record
-- of the two-person rule), yet the account restriction's requests about a withdrawn member are
-- 신고·제재 기록 that #184 deletes after their period (ADR-0085 결과 5). This function is the
-- narrowest door: it deletes, of the ids it is given, only requests of the account restriction's
-- four kinds (#139) that are no longer pending, about a member who has closed the account, and
-- that no action or end change names any more; every other id is left alone, so an admin grant's
-- requests (#171) and a live member's stay whoever calls it. The member is read from the request
-- alone, whose columns migration 0021's trigger freezes and buddha_app cannot delete: an apply's
-- `target_id`, and a change's `payload.userId` (the restriction's member, as the API writes it
-- with `actionId`). Not from the restriction a change names: buddha_app may delete an action (the
-- worker does, before calling this) and could insert another under its id, so the action proves
-- nothing about whose the request is — a live member's restriction deleted outside #184 leaves its
-- requests standing. A change request with no `userId` is never deleted. SECURITY DEFINER as the
-- table's owner (the migration role), with a fixed search_path; EXECUTE for buddha_app only. The
-- period itself is the caller's (the worker's job reads the release setting); this bounds what any
-- call can ever delete. Returns how many it deleted.
CREATE FUNCTION retention_delete_approval_requests(ids uuid[]) RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE
  deleted integer;
BEGIN
  DELETE FROM "approval_requests" r
   WHERE r."id" = ANY(ids)
     AND r."kind" IN ('account_restriction', 'account_restriction_shorten',
                      'account_restriction_lift', 'account_restriction_cancel')
     AND r."status" <> 'pending'
     AND CASE
           WHEN r."kind" = 'account_restriction' AND r."target_type" = 'user' THEN
             EXISTS (SELECT FROM "profiles" p
                      WHERE p."user_id" = r."target_id" AND p."closed_at" IS NOT NULL)
           WHEN r."kind" <> 'account_restriction' AND r."target_type" = 'moderation_action' THEN
             EXISTS (SELECT FROM "profiles" p
                      WHERE p."user_id" = r."payload"->>'userId' AND p."closed_at" IS NOT NULL)
           ELSE false
         END
     AND NOT EXISTS (SELECT FROM "moderation_actions" a
                      WHERE a."approval_id" = r."id" OR a."cancel_approval_id" = r."id")
     AND NOT EXISTS (SELECT FROM "restriction_end_changes" c WHERE c."approval_id" = r."id");
  GET DIAGNOSTICS deleted = ROW_COUNT;
  RETURN deleted;
END;
$$;--> statement-breakpoint
REVOKE ALL ON FUNCTION retention_delete_approval_requests(uuid[]) FROM PUBLIC;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION retention_delete_approval_requests(uuid[]) TO buddha_app;